def get_ludic(n):
    if n < 1:
        return []

    # Start with a list containing all numbers from 1 to n
    ludics = list(range(1, n + 1))

    # The first Ludic number is always the first element (index 0)
    idx = 0

    while True:
        current_ludic = ludics[idx]

        if current_ludic > n or len(ludics) == 0:
            break

        # Remove every k-th remaining number, where k is the value of the current Ludic number
        count_to_remove = current_ludic

        while count_to_remove >= len(ludics):
            ludics.pop()

        if not ludics or idx == 0:
            break

        # Remove elements starting from index (idx + k) with step k
        start_index = idx + current_ludic - 1
        for i in range(start_index, len(ludics), current_ludic):
            ludics.pop(i)

    return ludics

